// Lote 1a, tool 4: the simulated wind, a port of src/shared/wind.ts. Pure C# (no UnityEngine), no clock and no System.Random (the randomness is mulberry32 of
// Rng.cs), so the EditMode golden test (contracts/golden/wind.json, generated by the web's own code) reproduces it.
//
// The wind belongs to the SIMULATOR only (SimState.cfg.wind): it is local state of the model and never travels on the wire. In PX4 SITL the wind is Gazebo's
// and is neither read nor offered. Everything it produces is simulated.
//
// Frames: local NED (n north, e east), m/s. `fromDeg` is the meteorological direction: where the wind comes FROM, clockwise from north.

using System;
using System.Collections.Generic;
using System.Globalization;
using WebGL.Telemetry.Json;

namespace WebGL.Telemetry
{
    /// <summary>Wind of the simulator. All zero = the model of before the tool existed (contracts/golden/flightsim.json does not change).</summary>
    public sealed class WindConfig
    {
        /// <summary>Mean speed, m/s.</summary>
        public double speed;
        /// <summary>Direction it comes FROM, degrees clockwise from north (0 = a north wind that blows towards the south).</summary>
        public double fromDeg;
        /// <summary>Standard deviation of the gust of each horizontal axis, m/s.</summary>
        public double gustSigma;
        /// <summary>Correlation time of the gust, s.</summary>
        public double gustTau = 2;
        /// <summary>32-bit seed of the gust generator (unsigned integer).</summary>
        public double seed = 1;

        public WindConfig Clone() => new WindConfig { speed = speed, fromDeg = fromDeg, gustSigma = gustSigma, gustTau = gustTau, seed = seed };
    }

    /// <summary>Any members of the wind (null = leave as is); the seed is a double so that 1.5 or 2^32 can be refused like the web does.</summary>
    public sealed class WindPatch
    {
        public double? speed, fromDeg, gustSigma, gustTau, seed;
    }

    /// <summary>Gust of each horizontal axis and the state of the generator that feeds it (part of SimState).</summary>
    public sealed class WindState
    {
        public double gn, ge;
        public Rng rng;
        public WindState(double seed) { rng = new Rng(seed); }
    }

    public static class Wind
    {
        public const double SpeedMin = 0, SpeedMax = 12, FromMin = 0, FromMax = 360, GustMin = 0, GustMax = 4, TauMin = 0.5, TauMax = 10, SeedMax = 4294967295;
        /// <summary>The wind adds this acceleration per m/s of wind to the vehicle, 1/s.</summary>
        public const double Push = 0.25;

        public static WindConfig Default() => new WindConfig();

        static bool Finite(double x) => !double.IsNaN(x) && !double.IsInfinity(x);
        /// <summary>JS template-literal number: 12, 0.5, 4294967295.</summary>
        static string Num(double x) => x.ToString("R", CultureInfo.InvariantCulture);

        /// <summary>Checks a proposed wind against the ranges of the spec. `detail` is Spanish like the acks of the simulator; `code` is what a UI translates.</summary>
        public static ConfigCheck Validate(WindConfig w)
        {
            if (!Finite(w.speed) || !Finite(w.fromDeg) || !Finite(w.gustSigma) || !Finite(w.gustTau) || !Finite(w.seed))
                return ConfigCheck.No("wind_not_finite", "valores de viento no válidos");
            if (w.speed < SpeedMin || w.speed > SpeedMax)
                return ConfigCheck.No("wind_speed_range", "la velocidad del viento debe estar entre " + Num(SpeedMin) + " y " + Num(SpeedMax) + " m/s", SpeedMin, SpeedMax);
            if (w.fromDeg < FromMin || w.fromDeg > FromMax)
                return ConfigCheck.No("wind_from_range", "la dirección del viento debe estar entre " + Num(FromMin) + " y " + Num(FromMax) + " grados", FromMin, FromMax);
            if (w.gustSigma < GustMin || w.gustSigma > GustMax)
                return ConfigCheck.No("wind_gust_range", "las ráfagas deben estar entre " + Num(GustMin) + " y " + Num(GustMax) + " m/s", GustMin, GustMax);
            if (w.gustTau < TauMin || w.gustTau > TauMax)
                return ConfigCheck.No("wind_tau_range", "el tiempo de ráfaga debe estar entre " + Num(TauMin) + " y " + Num(TauMax) + " s", TauMin, TauMax);
            if (w.seed != Math.Floor(w.seed) || w.seed < 0 || w.seed > SeedMax)
                return ConfigCheck.No("wind_seed", "la semilla es un entero de 32 bits sin signo", 0, SeedMax);
            return ConfigCheck.Ok;
        }

        /// <summary>Mean wind in NED, m/s: -speed * (cos fromDeg, sin fromDeg) (a wind from the north blows towards the south).</summary>
        public static void Mean(WindConfig w, out double n, out double e)
        {
            double a = w.fromDeg * Math.PI / 180;
            n = -w.speed * Math.Cos(a);
            e = -w.speed * Math.Sin(a);
        }

        /// <summary>
        /// One step of the gusts, once per Step call: a first-order Gauss-Markov process per horizontal axis with the exact discretisation
        /// g = g*a + sigma*sqrt(1 - a^2)*xi, a = exp(-dt/tau), xi standard normal (north first, then east). It always draws its two normals, so the generator
        /// advances the same with or without gusts. Mutates `g`.
        /// </summary>
        public static void StepGusts(WindState g, WindConfig w, double dt)
        {
            double a = Math.Exp(-dt / w.gustTau);
            double k = w.gustSigma * Math.Sqrt(1 - a * a);
            double xn = g.rng.Normal();
            double xe = g.rng.Normal();
            g.gn = g.gn * a + k * xn;
            g.ge = g.ge * a + k * xe;
        }

        /// <summary>Tolerant reader of what the app stores (the WindConfig as JSON): anything invalid falls back to the defaults (no wind).</summary>
        public static WindConfig Parse(string raw)
        {
            try
            {
                if (raw != null && TelemetryJson.TryParse(raw, out object v, out _) && v is Dictionary<string, object> o)
                {
                    double N(string k) => o.TryGetValue(k, out object x) && x is double d ? d : double.NaN;
                    var w = new WindConfig { speed = N("speed"), fromDeg = N("fromDeg"), gustSigma = N("gustSigma"), gustTau = N("gustTau"), seed = N("seed") };
                    if (Validate(w).ok) return w;
                }
            }
            catch (Exception) { /* falls through: no wind */ }
            return Default();
        }

        /// <summary>The JSON the app stores under Desk_SimWind.</summary>
        public static string ToJson(WindConfig w) =>
            "{\"speed\":" + TelemetryJson.Num(w.speed) + ",\"fromDeg\":" + TelemetryJson.Num(w.fromDeg) + ",\"gustSigma\":" + TelemetryJson.Num(w.gustSigma) +
            ",\"gustTau\":" + TelemetryJson.Num(w.gustTau) + ",\"seed\":" + TelemetryJson.Num(w.seed) + "}";

        /// <summary>The 8 compass points of a direction (0 = N, 1 = NE ... 7 = NW): the index into the names of the language.</summary>
        public static int CompassIndex(double deg)
        {
            double d = ((deg % 360) + 360) % 360;
            return (int)((JsMath.Round(d / 45) % 8 + 8) % 8);
        }
    }
}
